import type { PyqPaper } from '../types';
export const main20240127S1: PyqPaper = { id: 'main-2024-01-27-s1', exam: 'JEE Main', year: 2024, session: 'January', date: '2024-01-27', shift: 1, source: 'MathonGo compilation of JEE Main 2024 (27 Jan, Shift 1)', answerSource: 'answer-key', questions: [
  { id: 'main-2024-01-27-s1-Q1', number: 1, subject: 'Physics', chapter: 'Units, Dimensions and Errors', topic: 'Dimensions and Dimensional Formulae', pattern: 'Statements on dimensions of h, L, momentum, torque', type: 'single', difficulty: 'Easy', question: 'Given below are two statements:\nStatement (I): Planck\'s constant and angular momentum have the same dimensions.\nStatement (II): Linear momentum and moment of force have the same dimensions.\nIn light of the above statements, choose the correct answer from the options given below:', options: ['Statement I is true but Statement II is false', 'Both Statement I and Statement II are false', 'Both Statement I and Statement II are true', 'Statement I is false but Statement II is true'], answers: ['Statement I is true but Statement II is false'], solution: 'h and L both have dimensions ML²T⁻¹, so I is true. Momentum is MLT⁻¹ while moment of force is ML²T⁻², so II is false.' },
  { id: 'main-2024-01-27-s1-Q2', number: 2, subject: 'Physics', chapter: 'Kinematics', topic: 'Motion with Variable Acceleration', pattern: 'Velocity from position vector by differentiation', type: 'single', difficulty: 'Easy', question: 'Position of an ant (S in metres) moving in the Y–Z plane is given by S = 2t² ĵ + 5 k̂ (t in seconds). The magnitude and direction of the velocity of the ant at t = 1 s will be:', options: ['16 m s⁻¹ in y-direction', '4 m s⁻¹ in x-direction', '9 m s⁻¹ in z-direction', '4 m s⁻¹ in y-direction'], answers: ['4 m s⁻¹ in y-direction'], solution: 'v = dS/dt = 4t ĵ, so at t = 1 s the velocity is 4 m s⁻¹ along y.' },
  { id: 'main-2024-01-27-s1-Q3', number: 3, subject: 'Physics', chapter: 'Laws of Motion', topic: 'Dynamics of Circular Motion and Banking of Roads', pattern: 'Banking height of rail from speed and radius', type: 'single', difficulty: 'Medium', question: 'A train is moving with a speed of 12 m s⁻¹ on rails which are 1.5 m apart. To negotiate a curve of radius 400 m, the height by which the outer rail should be raised with respect to the inner rail is (Given g = 10 m s⁻²):', options: ['6.0 cm', '5.4 cm', '4.8 cm', '4.2 cm'], answers: ['5.4 cm'], solution: 'tanθ = v²/(rg) = 144/4000 = 0.036; h = l tanθ = 1.5 × 0.036 = 0.054 m = 5.4 cm.' },
  { id: 'main-2024-01-27-s1-Q4', number: 4, subject: 'Physics', chapter: 'Work, Energy and Power', topic: 'Kinetic Energy and the Work-Energy Theorem', pattern: 'Momentum ratio at equal kinetic energy', type: 'single', difficulty: 'Easy', question: 'Two bodies of mass 4 g and 25 g are moving with equal kinetic energies. The ratio of magnitude of their linear momenta is:', options: ['3 : 5', '5 : 4', '2 : 5', '4 : 5'], answers: ['2 : 5'], solution: 'p = √(2mK) ∝ √m, so p₁:p₂ = √4 : √25 = 2 : 5.' },
  { id: 'main-2024-01-27-s1-Q5', number: 5, subject: 'Physics', chapter: 'Laws of Motion', topic: 'Conservation of Linear Momentum and Impulse', pattern: 'Velocity after mass added (momentum conservation)', type: 'single', difficulty: 'Easy', question: 'A body of mass 1000 kg is moving horizontally with a velocity 6 m s⁻¹. If 200 kg extra mass is added, the final velocity (in m s⁻¹) is:', options: ['6', '2', '3', '5'], answers: ['5'], solution: 'Momentum conservation: 1000 × 6 = 1200 v, so v = 5 m s⁻¹.' },
  { id: 'main-2024-01-27-s1-Q6', number: 6, subject: 'Physics', chapter: 'Gravitation', topic: 'Acceleration due to Gravity and Its Variation', pattern: 'g when radius halves at constant mass', type: 'single', difficulty: 'Easy', question: 'The acceleration due to gravity on the surface of earth is g. If the diameter of earth reduces to half of its original value and mass remains constant, then acceleration due to gravity on the surface of earth would be:', options: ['g/4', '2g', 'g/2', '4g'], answers: ['4g'], solution: 'g = GM/R² ∝ 1/R²; halving R gives 4g.' },
  { id: 'main-2024-01-27-s1-Q7', number: 7, subject: 'Physics', chapter: 'Mechanical Properties of Fluids', topic: 'Viscosity, Stokes\' Law and Terminal Velocity', pattern: 'Statements on surface tension, viscosity and pressure', type: 'single', difficulty: 'Easy', question: 'Given below are two statements:\nStatement (I): Viscosity of gases is greater than that of liquids.\nStatement (II): Surface tension of a liquid decreases due to the presence of insoluble impurities.\nIn light of the above statements, choose the most appropriate answer from the options given below:', options: ['Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct', 'Both Statement I and Statement II are incorrect', 'Both Statement I and Statement II are correct'], answers: ['Statement I is incorrect but Statement II is correct'], solution: 'Liquids are more viscous than gases, so I is wrong. Impurities lower surface tension, so II is right.' },
  { id: 'main-2024-01-27-s1-Q8', number: 8, subject: 'Physics', chapter: 'Thermodynamics', topic: 'First Law of Thermodynamics and Molar Specific Heats', pattern: 'Internal energy change from Cv, mass and ΔT', type: 'single', difficulty: 'Easy', question: '0.08 kg air is heated at constant volume through 5 °C. The specific heat of air at constant volume is 0.17 kcal kg⁻¹ °C⁻¹ and 1 J = 4.18 joule cal⁻¹. The change in its internal energy is approximately:', options: ['318 J', '298 J', '284 J', '142 J'], answers: ['284 J'], solution: 'ΔU = m c_v ΔT = 0.08 × 0.17 × 5 = 0.068 kcal = 68 cal ≈ 68 × 4.18 ≈ 284 J.' },
  { id: 'main-2024-01-27-s1-Q9', number: 9, subject: 'Physics', chapter: 'Kinetic Theory of Gases', topic: 'Kinetic Interpretation of Temperature and Molecular Speeds', pattern: 'Temperature from average kinetic energy per molecule', type: 'single', difficulty: 'Easy', question: 'The average kinetic energy of a monatomic molecule is 0.414 eV at temperature: (Use k_B = 1.38 × 10⁻²³ J mol⁻¹ K⁻¹)', options: ['3000 K', '3200 K', '1600 K', '1500 K'], answers: ['3200 K'], solution: 'KE = (3/2)kT, so T = 0.414 × 1.6×10⁻¹⁹ / (1.5 × 1.38×10⁻²³) ≈ 3200 K.' },
  { id: 'main-2024-01-27-s1-Q10', number: 10, subject: 'Physics', chapter: 'Electrostatic Potential and Capacitance', topic: 'Electric Potential and Potential Energy', pattern: 'Potential difference between points at equal distance from charge', type: 'single', difficulty: 'Easy', question: 'An electric charge 10⁻⁶ μC is placed at origin (0, 0) m of the X–Y co-ordinate system. Two points P and Q are situated at (√3, √3) m and (√6, 0) m respectively. The potential difference between the points P and Q will be:', options: ['√3 V', '√6 V', '0 V', '3 V'], answers: ['0 V'], solution: 'Both points are at distance √6 m from the charge, so they have equal potential and the difference is 0.' },
  { id: 'main-2024-01-27-s1-Q11', number: 11, subject: 'Physics', chapter: 'Current Electricity', topic: 'Combination of Resistors', pattern: 'Resistance cut into equal parts joined in parallel', type: 'single', difficulty: 'Easy', question: 'A wire of resistance R and length L is cut into 5 equal parts. If these parts are joined parallelly, then the resultant resistance will be:', options: ['R/25', 'R/5', '25R', '5R'], answers: ['R/25'], solution: 'Each part has R/5; five in parallel give (R/5)/5 = R/25.' },
  { id: 'main-2024-01-27-s1-Q12', number: 12, subject: 'Physics', chapter: 'Current Electricity', topic: 'Wheatstone Bridge and Metre Bridge', pattern: 'Metre bridge with wire resistivity from balance length', type: 'single', difficulty: 'Medium', question: 'A wire of length 10 cm and radius √7 × 10⁻⁴ m is connected across the right gap of a meter bridge. When a resistance of 4.5 Ω is connected on the left gap by using a resistance box, the balance length is found to be at 60 cm from the left end. If the resistivity of the wire is R × 10⁻⁷ Ω m, then the value of R is:', options: ['63', '70', '66', '35'], answers: ['66'], solution: '4.5/X = 60/40 gives X = 3 Ω. ρ = XA/l = 3 × π × 7×10⁻⁸ / 0.1 ≈ 66 × 10⁻⁷ Ω m.' },
  { id: 'main-2024-01-27-s1-Q13', number: 13, subject: 'Physics', chapter: 'Moving Charges and Magnetism', topic: 'Combined Electric and Magnetic Fields, Cyclotron', pattern: 'Fields allowing undeflected proton', type: 'single', difficulty: 'Medium', question: 'A proton moving with a constant velocity passes through a region of space without any change in its velocity. If E and B represent the electric and magnetic fields respectively, then the region of space may have:\n(A) E = 0, B = 0; (B) E = 0, B ≠ 0; (C) E ≠ 0, B = 0; (D) E ≠ 0, B ≠ 0\nChoose the most appropriate answer from the options given below:', options: ['(A), (B) and (C) only', '(A), (C) and (D) only', '(A), (B) and (D) only', '(B), (C) and (D) only'], answers: ['(A), (B) and (D) only'], solution: 'Zero net force is possible if E = B = 0, if v ∥ B with E = 0, or if qE balances qv×B. With E ≠ 0 and B = 0 the force is nonzero, so (C) is excluded.' },
  { id: 'main-2024-01-27-s1-Q14', number: 14, subject: 'Physics', chapter: 'Electromagnetic Induction', topic: 'Magnetic Flux, Faraday\'s Law and Lenz\'s Law', pattern: 'Average emf when loop is removed from field at an angle', type: 'single', difficulty: 'Easy', question: 'A rectangular loop of length 2.5 m and width 2 m is placed at 60° to a magnetic field of 4 T. The loop is removed from the field in 10 s. The average emf induced in the loop during this time is:', options: ['−2 V', '+2 V', '+1 V', '−1 V'], answers: ['+1 V'], solution: 'Φ = BA cos60° = 4 × 5 × 0.5 = 10 Wb, final flux is 0; emf = −ΔΦ/Δt = −(0 − 10)/10 = +1 V.' },
  { id: 'main-2024-01-27-s1-Q15', number: 15, subject: 'Physics', chapter: 'Electromagnetic Waves', topic: 'Energy, Intensity and Momentum of EM Waves', pattern: 'Energy density/intensity from field amplitude', type: 'single', difficulty: 'Easy', question: 'A plane electromagnetic wave propagating in x-direction is described by E_y = (200 V m⁻¹) sin[1.5 × 10⁷ t − 0.05 x]. The intensity of the wave is: (Use ε₀ = 8.85 × 10⁻¹² C² N⁻¹ m⁻²)', options: ['35.4 W m⁻²', '53.1 W m⁻²', '26.6 W m⁻²', '106.2 W m⁻²'], answers: ['53.1 W m⁻²'], solution: 'c = ω/k = 3×10⁸; I = ½ ε₀ E₀² c = 0.5 × 8.85×10⁻¹² × 4×10⁴ × 3×10⁸ ≈ 53.1 W m⁻².' },
  { id: 'main-2024-01-27-s1-Q16', number: 16, subject: 'Physics', chapter: 'Ray Optics and Optical Instruments', topic: 'Prism, Minimum Deviation and Dispersion', pattern: 'Minimum deviation when n = cot(A/2)', type: 'single', difficulty: 'Medium', question: 'If the refractive index of the material of a prism is cot(A/2), where A is the angle of prism, then the angle of minimum deviation will be:', options: ['π − 2A', 'π/2 − 2A', 'π − A', 'π/2 − A'], answers: ['π − 2A'], solution: 'n = sin((A+δ)/2)/sin(A/2) = cos(A/2)/sin(A/2) gives sin((A+δ)/2) = cos(A/2), so (A+δ)/2 = π/2 − A/2 and δ = π − 2A.' },
  { id: 'main-2024-01-27-s1-Q17', number: 17, subject: 'Physics', chapter: 'Ray Optics and Optical Instruments', topic: 'Refraction at Spherical Surfaces and Thin Lenses', pattern: 'Photocurrent when lens focal length changes', type: 'single', difficulty: 'Medium', question: 'A convex lens of focal length 40 cm forms an image of an extended source of light on a photoelectric cell. A current I is produced. The lens is replaced by another convex lens having the same diameter but focal length 20 cm. The photoelectric current now is:', options: ['I/2', '4I', '2I', 'I'], answers: ['I'], solution: 'The same lens diameter collects the same total light from the source; the image is smaller but all the light still falls on the cell, so the current stays I.' },
  { id: 'main-2024-01-27-s1-Q18', number: 18, subject: 'Physics', chapter: 'Atoms', topic: 'Bohr Model: Radius, Velocity and Energy', pattern: 'Bohr orbit radius ratio from n²', type: 'single', difficulty: 'Easy', question: 'The radius of the third stationary orbit of electron for Bohr\'s atom is R. The radius of the fourth stationary orbit will be:', options: ['(4/3)R', '(16/9)R', '(3/4)R', '(9/16)R'], answers: ['(16/9)R'], solution: 'r ∝ n², so r₄ = (16/9) r₃ = (16/9)R.' },
  { id: 'main-2024-01-27-s1-Q19', number: 19, subject: 'Physics', chapter: 'Semiconductor Electronics', topic: 'p-n Junction: Formation and Biasing', pattern: 'Identify reverse biased diode circuit', type: 'single', difficulty: 'Easy', question: 'Which of the following circuits is reverse-biased?', options: ['+2 V connected through a resistor to the anode of a diode whose cathode is grounded', 'Ground connected to the anode of a diode, which is in series with a resistor connected to −5 V', '+2 V connected to the anode of a diode in series with a resistor connected to −10 V', '+2 V connected to the anode of a diode in series with a resistor connected to +4 V'], answers: ['+2 V connected to the anode of a diode in series with a resistor connected to +4 V'], figure: 'Four circuits each with a diode and a resistor: (1) +2 V - R - diode - ground; (2) ground - diode - R - (-5 V); (3) +2 V - diode - R - (-10 V); (4) +2 V - diode - R - +4 V (diode arrow pointing from the +2 V side).', solution: 'A diode is reverse-biased when the cathode side is at higher potential: in the last circuit the anode is at +2 V and the cathode side at +4 V. The other three are forward-biased.' },
  { id: 'main-2024-01-27-s1-Q20', number: 20, subject: 'Physics', chapter: 'Units, Dimensions and Errors', topic: 'Vernier Calipers and Screw Gauge', pattern: 'Quantity not measurable by spherometer', type: 'single', difficulty: 'Easy', question: 'Identify the physical quantity that cannot be measured using spherometer:', options: ['Radius of curvature of concave surface', 'Specific rotation of liquids', 'Thickness of thin plates', 'Radius of curvature of convex surface'], answers: ['Specific rotation of liquids'], solution: 'A spherometer measures radii of curvature of spherical surfaces and thicknesses of thin plates; specific rotation needs a polarimeter.' },
  { id: 'main-2024-01-27-s1-Q21', number: 21, subject: 'Physics', chapter: 'Kinematics', topic: 'Equations of Motion in a Straight Line', pattern: 'Speed after time from constant acceleration and x-position', type: 'numerical', difficulty: 'Medium', question: 'A particle starts from origin at t = 0 with a velocity 5 î m s⁻¹ and moves in x–y plane under action of a force which produces a constant acceleration of (3 î + 2 ĵ) m s⁻². If the x-coordinate of the particle at that instant is 84 m, then the speed of the particle at this time is √α m s⁻¹. The value of α is ______.', answers: ['673'], solution: 'x = 5t + 1.5t² = 84 gives t = 6 s. Then vₓ = 5 + 18 = 23, v_y = 12, so v² = 529 + 144 = 673.' },
  { id: 'main-2024-01-27-s1-Q22', number: 22, subject: 'Physics', chapter: 'Rotational Motion', topic: 'Moment of Inertia and Radius of Gyration', pattern: 'MI of system of four masses at square corners about vertex axis', type: 'numerical', difficulty: 'Easy', question: 'Four particles, each of mass 1 kg are placed at four corners of a square of side 2 m. The moment of inertia of the system about an axis perpendicular to its plane and passing through one of its vertex is ______ kg m².', answers: ['16'], solution: 'Distances from the vertex: 0, 2, 2, 2√2, so I = 0 + 4 + 4 + 8 = 16 kg m².' },
  { id: 'main-2024-01-27-s1-Q23', number: 23, subject: 'Physics', chapter: 'Mechanical Properties of Solids', topic: 'Bulk Modulus, Shear Modulus and Poisson\'s Ratio', pattern: 'Volume strain of water at ocean depth', type: 'numerical', difficulty: 'Easy', question: 'If average depth of an ocean is 4000 m and the bulk modulus of water is 2 × 10⁹ N m⁻², then fractional compression ΔV/V of water at the bottom of ocean is α × 10⁻². The value of α is ______. (Given, g = 10 m s⁻², ρ = 1000 kg m⁻³)', answers: ['2'], solution: 'ΔP = ρgh = 4×10⁷ Pa; ΔV/V = ΔP/B = 4×10⁷/2×10⁹ = 2×10⁻².' },
  { id: 'main-2024-01-27-s1-Q24', number: 24, subject: 'Physics', chapter: 'Oscillations (SHM)', topic: 'Velocity, Acceleration and Energy in SHM', pattern: 'Displacement in SHM from speed at mean position', type: 'numerical', difficulty: 'Medium', question: 'A particle executes simple harmonic motion with an amplitude of 4 cm. At the mean position, velocity of the particle is 10 cm s⁻¹. The distance of the particle from the mean position when its speed becomes 5 cm s⁻¹ is √α cm, where α = ______.', answers: ['12'], solution: 'ωA = 10 gives ω = 2.5 s⁻¹. v² = ω²(A² − x²): 25 = 6.25(16 − x²), so x² = 12.' },
  { id: 'main-2024-01-27-s1-Q25', number: 25, subject: 'Physics', chapter: 'Electric Charges and Fields', topic: 'Electric Field and Field Lines', pattern: 'Tension in charged ring from central point charge', type: 'numerical', difficulty: 'Hard', question: 'A thin metallic wire having cross sectional area of 10⁻⁴ m² is used to make a ring of radius 30 cm. A positive charge of 2π C is uniformly distributed over the ring, while another positive charge of 30 pC is kept at the centre of the ring. The tension in the ring is ______ N; provided that the ring does not get deformed (neglect the influence of gravity). (Given, 1/4πε₀ = 9 × 10⁹ SI units)', answers: ['3'], solution: 'For an element subtending dθ: 2T sin(dθ/2) = dq·E, so T = (Q/2π)·kq/R² = 1 × 9×10⁹ × 30×10⁻¹² / 0.09 = 3 N.' },
  { id: 'main-2024-01-27-s1-Q26', number: 26, subject: 'Physics', chapter: 'Electrostatic Potential and Capacitance', topic: 'Combination of Capacitors and Charge Sharing', pattern: 'Charge on capacitor across bridge midpoints', type: 'numerical', difficulty: 'Medium', question: 'The charge accumulated on the capacitor connected in the following circuit is ______ μC. (Given C = 150 μF)', answers: ['400'], figure: 'A 10 V battery feeds a bridge: top vertex to A via R1 = 1 Ω and to B via R3 = 6 Ω; A to bottom via R2 = 2 Ω and B to bottom via R4 = 4 Ω; capacitor C = 150 μF connected between A and B.', solution: 'Take the battery negative terminal as 0 V. Left branch divider (1 Ω, 2 Ω): V_A = 10 × 2/3 = 20/3 V. Right branch (6 Ω, 4 Ω): V_B = 10 × 4/10 = 4 V. ΔV = 8/3 V, Q = 150 × 8/3 = 400 μC.' },
  { id: 'main-2024-01-27-s1-Q27', number: 27, subject: 'Physics', chapter: 'Moving Charges and Magnetism', topic: 'Ampere\'s Circuital Law and its Applications', pattern: 'Field midway between opposite parallel currents', type: 'numerical', difficulty: 'Easy', question: 'Two long, straight wires carry equal currents in opposite directions as shown in figure. The separation between the wires is 5.0 cm. The magnitude of the magnetic field at a point P midway between the wires is ______ μT. (Given: μ₀ = 4π × 10⁻⁷ T m A⁻¹)', answers: ['160'], figure: 'Two parallel vertical wires 5.0 cm apart, each carrying 10 A in opposite directions (left wire up, right wire down); P lies midway between them.', solution: 'Fields add: B = 2 × μ₀I/(2π × 0.025) = 2 × 8×10⁻⁵ = 1.6×10⁻⁴ T = 160 μT.' },
  { id: 'main-2024-01-27-s1-Q28', number: 28, subject: 'Physics', chapter: 'Electromagnetic Induction', topic: 'Mutual Inductance', pattern: 'Max induced emf from mutual inductance', type: 'numerical', difficulty: 'Easy', question: 'Two coils have mutual inductance 0.002 H. The current changes in the first coil according to the relation i = i₀ sin ωt, where i₀ = 5 A and ω = 50π rad s⁻¹. The maximum value of emf in the second coil is π/α V. The value of α is ______.', answers: ['2'], solution: 'emf_max = M i₀ ω = 0.002 × 5 × 50π = π/2 V, so α = 2.' },
  { id: 'main-2024-01-27-s1-Q29', number: 29, subject: 'Physics', chapter: 'Ray Optics and Optical Instruments', topic: 'Refraction, Snell\'s Law and Apparent Depth', pattern: 'Apparent depth through two liquid layers', type: 'numerical', difficulty: 'Easy', question: 'Two immiscible liquids of refractive indices 8/5 and 3/2 respectively are put in a beaker as shown in the figure. The height of each column is 6 cm. A coin is placed at the bottom of the beaker. For near normal vision, the apparent depth of the coin is α/4 cm. The value of α is ______.', answers: ['31'], figure: 'Beaker with a bottom liquid layer (μ₁ = 8/5, 6 cm) and a top layer (μ₂ = 3/2, 6 cm); the coin lies at the bottom.', solution: 'Apparent depth = 6/(8/5) + 6/(3/2) = 3.75 + 4 = 7.75 = 31/4 cm.' },
  { id: 'main-2024-01-27-s1-Q30', number: 30, subject: 'Physics', chapter: 'Nuclei', topic: 'Mass Defect and Binding Energy', pattern: 'Energy released in fission from BE per nucleon', type: 'numerical', difficulty: 'Easy', question: 'In a nuclear fission process, a high mass nuclide (A ≈ 236) with binding energy 7.6 MeV/Nucleon dissociated into two middle mass nuclides (A ≈ 118), having binding energy of 8.6 MeV/Nucleon. The energy released in the process would be ______ MeV.', answers: ['236'], solution: 'Q = 236 × (8.6 − 7.6) = 236 MeV.' },
  { id: 'main-2024-01-27-s1-Q31', number: 31, subject: 'Chemistry', chapter: 'd- and f-Block Elements', topic: 'Lanthanoids and Lanthanoid Contraction', pattern: 'Electronic configuration of neodymium', type: 'single', difficulty: 'Easy', question: 'The electronic configuration for Neodymium is: [Atomic Number for Neodymium 60]', options: ['[Xe] 4f⁴ 6s²', '[Xe] 5f⁴ 7s²', '[Xe] 4f⁶ 6s²', '[Xe] 4f¹ 5d¹ 6s²'], answers: ['[Xe] 4f⁴ 6s²'], solution: 'Nd is the fourth lanthanoid after Ce, with configuration [Xe] 4f⁴ 6s².' },
  { id: 'main-2024-01-27-s1-Q32', number: 32, subject: 'Chemistry', chapter: 'd- and f-Block Elements', topic: 'Magnetic Properties and Colour', pattern: 'Highest magnetic moment from d-configuration', type: 'single', difficulty: 'Easy', question: 'Which of the following electronic configuration would be associated with the highest magnetic moment?', options: ['[Ar] 3d⁷', '[Ar] 3d⁸', '[Ar] 3d³', '[Ar] 3d⁶'], answers: ['[Ar] 3d⁶'], solution: 'High-spin counts: d⁷ has 3, d⁸ has 2, d³ has 3, d⁶ has 4 unpaired electrons; d⁶ is the highest.' },
  { id: 'main-2024-01-27-s1-Q33', number: 33, subject: 'Chemistry', chapter: 'Chemical Bonding', topic: 'Bond Parameters, Resonance and Dipole Moment', pattern: 'Identify polar molecule', type: 'single', difficulty: 'Easy', question: 'Choose the polar molecule from the following:', options: ['CCl₄', 'CO₂', 'CH₂ = CH₂', 'CHCl₃'], answers: ['CHCl₃'], solution: 'CCl₄, CO₂ and C₂H₄ are symmetric with zero dipole moment; CHCl₃ is not symmetric and is polar.' },
  { id: 'main-2024-01-27-s1-Q34', number: 34, subject: 'Chemistry', chapter: 'Amines', topic: 'Basicity of Amines', pattern: 'Strongest Bronsted base among amines and aromatics', type: 'single', difficulty: 'Easy', question: 'Which of the following is the strongest Bronsted base?', options: ['Aniline', 'Diphenylamine', 'Pyrrole', 'Pyrrolidine'], answers: ['Pyrrolidine'], figure: 'Structures: (1) aniline, (2) diphenylamine, (3) pyrrole, (4) pyrrolidine.', solution: 'Aniline, diphenylamine and pyrrole have the nitrogen lone pair delocalised into the ring; pyrrolidine is a localised secondary aliphatic amine and the strongest base.' },
  { id: 'main-2024-01-27-s1-Q35', number: 35, subject: 'Chemistry', chapter: 'Ionic Equilibrium', topic: 'Salt Hydrolysis', pattern: 'Statements on hydrolysis of ammonium carbonate', type: 'single', difficulty: 'Medium', question: 'Given below are two statements:\nStatement (I): Aqueous solution of ammonium carbonate is basic.\nStatement (II): Acidic/basic nature of salt solution of a salt of weak acid and weak base depends on K_a and K_b value of acid and the base forming it.\nIn light of the above statements, choose the most appropriate answer from the options given below:', options: ['Both Statement I and Statement II are correct', 'Statement I is correct but Statement II is incorrect', 'Both Statement I and Statement II are incorrect', 'Statement I is incorrect but Statement II is correct'], answers: ['Both Statement I and Statement II are correct'], solution: 'For (NH₄)₂CO₃, K_b(NH₃) > K_a(HCO₃⁻) so the solution is basic, and in general the nature depends on the relative K_a and K_b. Both statements are correct.' },
  { id: 'main-2024-01-27-s1-Q36', number: 36, subject: 'Chemistry', chapter: 'p-Block Elements (Groups 13-14)', topic: 'Group 13: General Trends and Inert Pair Effect', pattern: 'Why boron has unusually high melting point', type: 'single', difficulty: 'Easy', question: 'Given below are two statements: one is labelled as Assertion (A) and the other is labelled as Reason (R).\nAssertion (A): Melting point of Boron (2453 K) is unusually high in group 13 elements.\nReason (R): Solid Boron has very strong crystalline lattice.\nIn light of the above statements, choose the most appropriate answer from the options given below:', options: ['Both (A) and (R) are correct but (R) is not the correct explanation of (A)', 'Both (A) and (R) are correct and (R) is the correct explanation of (A)', '(A) is true but (R) is false', '(A) is false but (R) is true'], answers: ['Both (A) and (R) are correct and (R) is the correct explanation of (A)'], solution: 'Boron exists as a very strong covalent crystalline network, which explains its unusually high melting point.' },
  { id: 'main-2024-01-27-s1-Q37', number: 37, subject: 'Chemistry', chapter: 'Organic Chemistry - Basic Principles', topic: 'IUPAC Nomenclature', pattern: 'IUPAC name of substituted cyclohexane', type: 'single', difficulty: 'Easy', question: 'IUPAC name of the following compound (P) is:', options: ['1-Ethyl-5,5-dimethylcyclohexane', '3-Ethyl-1,1-dimethylcyclohexane', '1-Ethyl-3,3-dimethylcyclohexane', '1,1-Dimethyl-3-ethylcyclohexane'], answers: ['3-Ethyl-1,1-dimethylcyclohexane'], figure: 'Structure of compound (P) not visible in the source image; it is a cyclohexane ring with two methyl groups on one carbon and an ethyl group on the carbon two positions away.', solution: 'The ring carries a gem-dimethyl carbon (C1) and an ethyl at C3; the lowest locants {1,1,3} with alphabetical order (ethyl before dimethyl) give 3-ethyl-1,1-dimethylcyclohexane.' },
  { id: 'main-2024-01-27-s1-Q38', number: 38, subject: 'Chemistry', chapter: 'Organic Chemistry - Basic Principles', topic: 'IUPAC Nomenclature', pattern: 'Classify cyclohexene as organic compound type', type: 'single', difficulty: 'Easy', question: 'Cyclohexene is ______ type of an organic compound.', options: ['Benzenoid aromatic', 'Benzenoid non-aromatic', 'Acyclic', 'Alicyclic'], answers: ['Alicyclic'], figure: 'Skeletal structure of cyclohexene (six-membered ring with one C=C).', solution: 'Cyclohexene is a cyclic compound without an aromatic ring, so it is alicyclic.' },
  { id: 'main-2024-01-27-s1-Q39', number: 39, subject: 'Chemistry', chapter: 'Organic Chemistry - Basic Principles', topic: 'Acidity and Basicity of Organic Compounds', pattern: 'Most acidic hydrogen in diketone', type: 'single', difficulty: 'Medium', question: 'Which of the following has highly acidic hydrogen?', options: ['CH₃–CO–CO–CH₂CH₂CH₃', 'CH₃CH₂–CO–CH₂CH₂–CO–CH₃', 'CH₃CH₂CH₂–CO–CH₂CH₃', 'CH₃CH₂–CO–CH₂–CO–CH₂CH₃'], answers: ['CH₃CH₂–CO–CH₂–CO–CH₂CH₃'], figure: 'Four ketones drawn: (1) 1,2-diketone, (2) 1,4-diketone, (3) simple monoketone, (4) 1,3-diketone with CH₂ between two C=O groups.', solution: 'The CH₂ flanked by two C=O groups (a 1,3-dicarbonyl) gives a highly resonance-stabilised enolate, so it is the most acidic.' },
  { id: 'main-2024-01-27-s1-Q40', number: 40, subject: 'Chemistry', chapter: 'Alcohols, Phenols and Ethers', topic: 'Physical Properties and Acidity of Alcohols and Phenols', pattern: 'Acidity order of substituted phenols and alcohol', type: 'single', difficulty: 'Medium', question: 'The ascending order of acidity of –OH group in the following compounds is:\n(A) Bu–OH; (B) 4-nitrophenol; (C) 4-methoxyphenol; (D) phenol; (E) 2,4-dinitrophenol.\nChoose the correct answer from the options given below:', options: ['(A) < (D) < (C) < (B) < (E)', '(C) < (A) < (D) < (B) < (E)', '(C) < (D) < (B) < (A) < (E)', '(A) < (C) < (D) < (B) < (E)'], answers: ['(A) < (C) < (D) < (B) < (E)'], figure: 'Compounds: (A) Bu-OH, (B) p-O₂N-C₆H₄-OH, (C) p-MeO-C₆H₄-OH, (D) phenol, (E) 2,4-dinitrophenol.', solution: 'Alcohol is the least acidic; the electron-donating OMe reduces phenol acidity, while one NO₂ increases and two NO₂ increase it most: A < C < D < B < E.' },
  { id: 'main-2024-01-27-s1-Q41', number: 41, subject: 'Chemistry', chapter: 'Organic Chemistry - Basic Principles', topic: 'Isomerism', pattern: 'Highest enol content among cyclic polyketones', type: 'single', difficulty: 'Hard', question: 'Highest enol content will be shown by:', options: ['Cyclohexane-1,3-dione', 'Cyclohexane-1,3,5-trione', 'Cyclohexane-1,4-dione', 'Cyclohexane-1,2,3-trione'], answers: ['Cyclohexane-1,3,5-trione'], figure: 'Four six-membered ring ketones: (1) 1,3-dione, (2) 1,3,5-trione, (3) 1,4-dione, (4) 1,2,3-trione.', solution: 'Enolisation of the 1,3,5-trione gives phloroglucinol, which is aromatic, so its enol content is highest.' },
  { id: 'main-2024-01-27-s1-Q42', number: 42, subject: 'Chemistry', chapter: 'Solutions', topic: 'Non-ideal Solutions and Azeotropes', pattern: 'Negative deviation: effect on vapour pressure and boiling point', type: 'single', difficulty: 'Easy', question: 'A solution of two miscible liquids showing negative deviation from Raoult\'s law will have:', options: ['increased vapour pressure, increased boiling point', 'increased vapour pressure, decreased boiling point', 'decreased vapour pressure, decreased boiling point', 'decreased vapour pressure, increased boiling point'], answers: ['decreased vapour pressure, increased boiling point'], solution: 'Negative deviation means stronger A–B interactions, so the vapour pressure falls and the boiling point rises.' },
  { id: 'main-2024-01-27-s1-Q43', number: 43, subject: 'Chemistry', chapter: 'p-Block Elements (Groups 15-18)', topic: 'Interhalogen Compounds and Oxoacids of Halogens', pattern: 'Halogen with no variable oxidation state', type: 'single', difficulty: 'Easy', question: 'Element not showing variable oxidation state is:', options: ['Bromine', 'Iodine', 'Chlorine', 'Fluorine'], answers: ['Fluorine'], solution: 'Fluorine is the most electronegative and has no d orbitals, so it shows only −1.' },
  { id: 'main-2024-01-27-s1-Q44', number: 44, subject: 'Chemistry', chapter: 'd- and f-Block Elements', topic: 'Potassium Dichromate and Potassium Permanganate', pattern: 'Chromyl chloride test: products', type: 'single', difficulty: 'Easy', question: 'NaCl reacts with conc. H₂SO₄ and K₂Cr₂O₇ to give reddish fumes (B), which react with NaOH to give yellow solution (C). (B) and (C) respectively are:', options: ['CrO₂Cl₂, Na₂CrO₄', 'Na₂CrO₄, CrO₂Cl₂', 'CrO₂Cl₂, KHSO₄', 'CrO₂Cl₂, Na₂Cr₂O₇'], answers: ['CrO₂Cl₂, Na₂CrO₄'], solution: 'The chromyl chloride test gives red fumes of CrO₂Cl₂, which dissolve in NaOH to form yellow Na₂CrO₄.' },
  { id: 'main-2024-01-27-s1-Q45', number: 45, subject: 'Chemistry', chapter: 'Periodic Properties', topic: 'Modern Periodic Law and Classification of Elements', pattern: 'True/false statements on the periodic table', type: 'single', difficulty: 'Easy', question: 'Given below are two statements:\nStatement (I): The 4f and 5f-series of elements are placed separately in the Periodic table to preserve the principle of classification.\nStatement (II): s-block elements can be found in pure form in nature.\nIn light of the above statements, choose the most appropriate answer from the options given below:', options: ['Statement I is false but Statement II is true', 'Both Statement I and Statement II are true', 'Statement I is true but Statement II is false', 'Both Statement I and Statement II are false'], answers: ['Statement I is true but Statement II is false'], solution: 'f-series are kept separate to maintain the classification, so I is true. s-block metals are highly reactive and never occur free, so II is false.' },
  { id: 'main-2024-01-27-s1-Q46', number: 46, subject: 'Chemistry', chapter: 'p-Block Elements (Groups 13-14)', topic: 'Group 14: General Trends, Catenation and Allotropes of Carbon', pattern: 'Lead salt reactions: chromate, plumbite, acetate complex', type: 'single', difficulty: 'Medium', question: 'Yellow compound of lead chromate gets dissolved on treatment with hot NaOH solution. The product of lead formed is a:', options: ['Tetraanionic complex with coordination number six', 'Neutral complex with coordination number four', 'Dianionic complex with coordination number six', 'Dianionic complex with coordination number four'], answers: ['Dianionic complex with coordination number four'], solution: 'PbCrO₄ + 4NaOH → Na₂[Pb(OH)₄] + Na₂CrO₄; [Pb(OH)₄]²⁻ is dianionic with coordination number four.' },
  { id: 'main-2024-01-27-s1-Q47', number: 47, subject: 'Chemistry', chapter: 'Coordination Compounds', topic: 'Spectrochemical Series, Colour and Magnetism', pattern: 'Unpaired electrons / magnetic moment of complexes', type: 'single', difficulty: 'Medium', question: 'Consider the following complex ions: P = [FeF₆]³⁻, Q = [V(H₂O)₆]²⁺, R = [Fe(H₂O)₆]²⁺. The correct order of the complex ions, according to their spin only magnetic moment values (in B.M.) is:', options: ['R < Q < P', 'R < P < Q', 'Q < R < P', 'Q < P < R'], answers: ['Q < R < P'], solution: 'Fe³⁺ (d⁵, high spin) has 5 unpaired electrons, V²⁺ (d³) has 3, Fe²⁺ (d⁶, weak field) has 4, so Q < R < P.' },
  { id: 'main-2024-01-27-s1-Q48', number: 48, subject: 'Chemistry', chapter: 'Haloalkanes and Haloarenes', topic: 'Stereochemistry of Nucleophilic Substitution', pattern: 'Retention, racemisation or inversion in SN1 and SN2', type: 'single', difficulty: 'Easy', question: 'The correct statement regarding nucleophilic substitution reaction in a chiral alkyl halide is:', options: ['Retention occurs in SN1 reaction and inversion occurs in SN2 reaction.', 'Racemisation occurs in SN1 reaction and retention occurs in SN2 reaction.', 'Racemisation occurs in both SN1 and SN2 reactions.', 'Racemisation occurs in SN1 reaction and inversion occurs in SN2 reaction.'], answers: ['Racemisation occurs in SN1 reaction and inversion occurs in SN2 reaction.'], solution: 'SN1 proceeds through a planar carbocation giving racemisation; SN2 is a backside attack giving inversion.' },
  { id: 'main-2024-01-27-s1-Q49', number: 49, subject: 'Chemistry', chapter: 'Alcohols, Phenols and Ethers', topic: 'Physical Properties and Acidity of Alcohols and Phenols', pattern: 'Statements on nitrophenol acidity and Lucas test', type: 'single', difficulty: 'Easy', question: 'Given below are two statements:\nStatement (I): p-nitrophenol is more acidic than m-nitrophenol and o-nitrophenol.\nStatement (II): Ethanol will give immediate turbidity with Lucas reagent.\nIn light of the above statements, choose the correct answer from the options given below:', options: ['Statement I is true but Statement II is false', 'Both Statement I and Statement II are true', 'Both Statement I and Statement II are false', 'Statement I is false but Statement II is true'], answers: ['Statement I is true but Statement II is false'], solution: 'p-Nitrophenol is taken as more acidic than the m- and o-isomers (the key marks I true); primary ethanol gives no turbidity at room temperature with Lucas reagent, so II is false.' },
  { id: 'main-2024-01-27-s1-Q50', number: 50, subject: 'Chemistry', chapter: 'Biomolecules', topic: 'Nucleic Acids', pattern: 'Linkage joining nucleotides', type: 'single', difficulty: 'Easy', question: 'Two nucleotides are joined together by a linkage known as:', options: ['Phosphodiester linkage', 'Glycosidic linkage', 'Disulphide linkage', 'Peptide linkage'], answers: ['Phosphodiester linkage'], solution: 'Nucleotides are linked via a phosphodiester bond between the 3\' and 5\' carbons of sugars.' },
  { id: 'main-2024-01-27-s1-Q51', number: 51, subject: 'Chemistry', chapter: 'Some Basic Concepts (Mole Concept)', topic: 'Stoichiometry and Limiting Reagent', pattern: 'Mass of methane for given CO₂ from combustion', type: 'numerical', difficulty: 'Easy', question: 'Mass of methane required to produce 22 g of CO after complete combustion is ______ g. (Given molar mass in g mol⁻¹: C = 12.0, H = 1.0, O = 16.0)', answers: ['8'], solution: 'The key treats the 22 g as CO₂ from complete combustion (CH₄ + 2O₂ → CO₂ + 2H₂O): 22 g = 0.5 mol, so 0.5 mol CH₄ = 8 g.' },
  { id: 'main-2024-01-27-s1-Q52', number: 52, subject: 'Chemistry', chapter: 'Structure of Atom', topic: 'Quantum Numbers and Shapes of Orbitals', pattern: 'Count electrons for given quantum numbers', type: 'numerical', difficulty: 'Medium', question: 'The number of electrons present in all the completely filled subshells having n = 4 and s = +1/2 is ______ (Where n = principal quantum number and s = spin quantum number).', answers: ['16'], solution: 'Subshells 4s, 4p, 4d, 4f hold 1 + 3 + 5 + 7 = 16 orbitals, each with one electron of spin +1/2.' },
  { id: 'main-2024-01-27-s1-Q53', number: 53, subject: 'Chemistry', chapter: 'Chemical Bonding', topic: 'Molecular Orbital Theory', pattern: 'Sum of bond orders of CO and NO⁺', type: 'numerical', difficulty: 'Easy', question: 'Sum of bond order of CO and NO⁺ is ______.', answers: ['6'], solution: 'CO and NO⁺ are both 10-valence-electron species isoelectronic with N₂, each with bond order 3; the sum is 6.' },
  { id: 'main-2024-01-27-s1-Q54', number: 54, subject: 'Chemistry', chapter: 'Chemical Thermodynamics', topic: 'First Law and Work of Expansion', pattern: 'Heat from isothermal irreversible expansion against constant pressure', type: 'numerical', difficulty: 'Medium', question: 'If three moles of an ideal gas at 300 K expand isothermally from 30 dm³ to 45 dm³ against a constant opposing pressure of 80 kPa, then the amount of heat transferred is ______ J.', answers: ['1200'], solution: 'w = −pΔV = −80×10³ × 15×10⁻³ = −1200 J. Isothermal ideal gas has ΔU = 0, so q = +1200 J absorbed.' },
  { id: 'main-2024-01-27-s1-Q55', number: 55, subject: 'Chemistry', chapter: 'Hydrocarbons', topic: 'Electrophilic Aromatic Substitution and Directive Influence', pattern: 'Count meta directing groups', type: 'numerical', difficulty: 'Easy', question: 'Among the following, total number of meta directing functional groups is (Integer based): –OCH₃, –NO₂, –CN, –CH₃, –NHCOCH₃, –COR, –OH, –COOH, –Cl', answers: ['4'], solution: 'Meta directors: –NO₂, –CN, –COR, –COOH; the rest are ortho/para directing.' },
  { id: 'main-2024-01-27-s1-Q56', number: 56, subject: 'Chemistry', chapter: 'Hydrocarbons', topic: 'Aromaticity and Benzene', pattern: 'Count aromatic compounds from list', type: 'numerical', difficulty: 'Medium', question: 'Among the given organic compounds, the total number of aromatic compounds is ______.', answers: ['3'], figure: '(A) naphthalene; (B) benzylcyclohexene (benzene ring attached by CH₂ to a cyclohexene); (C) indene-type fused ring with a carbanion lone pair on the five-membered ring; (D) fluorenyl anion.', solution: 'Aromatic: (A) naphthalene, (C) the indenyl-type anion with a lone pair completing the cyclopentadienyl 6π system, and (D) the fluorenyl anion. (B) benzylcyclohexene is not counted by the key.' },
  { id: 'main-2024-01-27-s1-Q57', number: 57, subject: 'Chemistry', chapter: 'Hydrocarbons', topic: 'Reactions of Alkenes', pattern: 'Stereoisomers of anti-Markovnikov HBr adduct', type: 'numerical', difficulty: 'Medium', question: '3-Methylhex-2-ene on reaction with HBr in presence of peroxide forms an addition product (A). The number of possible stereoisomers for A is ______.', answers: ['4'], solution: 'Peroxide effect puts Br on C-2: 2-bromo-3-methylhexane, which has two chiral centres (C2, C3), so 2² = 4 stereoisomers.' },
  { id: 'main-2024-01-27-s1-Q58', number: 58, subject: 'Chemistry', chapter: 'Electrochemistry', topic: 'Electrolysis and Faraday\'s Laws', pattern: 'Faraday\'s first law: mass/charge/current', type: 'numerical', difficulty: 'Medium', question: 'The mass of silver (Molar mass of Ag: 108 g mol⁻¹) displaced by a quantity of electricity which displaces 5600 mL of O₂ at S.T.P. will be ______ g.', answers: ['108'], solution: '5600 mL O₂ = 0.25 mol, which needs 4 × 0.25 = 1 mol of electrons; 1 mol e⁻ deposits 1 mol Ag = 108 g.' },
  { id: 'main-2024-01-27-s1-Q59', number: 59, subject: 'Chemistry', chapter: 'Chemical Kinetics', topic: 'Rate of Reaction and Rate Law', pattern: 'Order from initial rate data', type: 'numerical', difficulty: 'Easy', question: 'Consider the following data for the given reaction 2HI(g) → H₂(g) + I₂(g): [HI] (mol L⁻¹) = 0.005, 0.01, 0.02; Rate (mol L⁻¹ s⁻¹) = 7.5×10⁻⁴, 3.0×10⁻³, 1.2×10⁻². The order of the reaction is ______.', answers: ['2'], solution: 'Doubling [HI] raises the rate by 4 (7.5×10⁻⁴ to 3.0×10⁻³, then to 1.2×10⁻²), so order = 2.' },
  { id: 'main-2024-01-27-s1-Q60', number: 60, subject: 'Chemistry', chapter: 'Redox Reactions', topic: 'Oxidation Number', pattern: 'Count compounds with sulphur in +4 state', type: 'numerical', difficulty: 'Easy', question: 'From the given list, the number of compounds with +4 oxidation state of Sulphur is ______: SO₃, H₂SO₃, SOCl₂, SF₄, BaSO₄, H₂S₂O₇', answers: ['3'], solution: 'S is +4 in H₂SO₃, SOCl₂ and SF₄; it is +6 in SO₃, BaSO₄ and H₂S₂O₇.' },
  { id: 'main-2024-01-27-s1-Q61', number: 61, subject: 'Mathematics', chapter: 'Complex Numbers', topic: 'Geometry of Complex Numbers: Loci and Rotation', pattern: 'Points equidistant from three given points', type: 'single', difficulty: 'Medium', question: 'If S = {z ∈ C : |z − i| = |z + i| = |z − 1|}, then n(S) is:', options: ['1', '0', '3', '2'], answers: ['1'], solution: '|z−i| = |z+i| gives the real axis; with z = x, |z+i| = |z−1| gives x² + 1 = (x−1)², so x = 0. Only z = 0 works (the circumcentre of i, −i, 1).' },
  { id: 'main-2024-01-27-s1-Q62', number: 62, subject: 'Mathematics', chapter: 'Sequences and Series', topic: 'Arithmetic Progression', pattern: 'Common terms of two APs', type: 'single', difficulty: 'Medium', question: 'The number of common terms in the progressions 4, 9, 14, 19, ..., up to 25th term and 3, 6, 9, 12, ..., up to 37th term is:', options: ['9', '5', '7', '8'], answers: ['7'], solution: 'First AP is 5n − 1 (max 124 at n = 25), second is 3m (max 111). Common terms are 9, 24, 39, ... with difference 15 and at most 111: 9 + 15k ≤ 111 gives k = 0..6, so 7 terms.' },
  { id: 'main-2024-01-27-s1-Q63', number: 63, subject: 'Mathematics', chapter: 'Binomial Theorem', topic: 'Properties and Sums of Binomial Coefficients', pattern: 'Sum of coefficients comparison', type: 'single', difficulty: 'Easy', question: 'If A denotes the sum of all the coefficients in the expansion of (1 − 3x + 10x²)ⁿ and B denotes the sum of all the coefficients in the expansion of (1 + x²)ⁿ, then:', options: ['A = B³', '3A = B', 'B = A³', 'A = 3B'], answers: ['A = B³'], solution: 'Put x = 1: A = 8ⁿ and B = 2ⁿ, so A = B³.' },
  { id: 'main-2024-01-27-s1-Q64', number: 64, subject: 'Mathematics', chapter: 'Permutations and Combinations', topic: 'Combinations and Their Properties', pattern: 'Ratio of nCr values bounds parameter', type: 'single', difficulty: 'Medium', question: 'ⁿ⁻¹Cᵣ = (k² − 8) ⁿCᵣ₊₁ if and only if:', options: ['2√2 < k ≤ 3', '2√3 < k ≤ 3√2', '2√3 < k < 3√3', '2√2 < k < 2√3'], answers: ['2√2 < k ≤ 3'], solution: 'ⁿCᵣ₊₁ = (n/(r+1)) ⁿ⁻¹Cᵣ, so k² − 8 = (r+1)/n, which lies in (0, 1] for 0 ≤ r ≤ n−1. Hence 8 < k² ≤ 9, i.e. 2√2 < k ≤ 3.' },
  { id: 'main-2024-01-27-s1-Q65', number: 65, subject: 'Mathematics', chapter: 'Straight Lines', topic: 'Slope and Angle Between Two Lines', pattern: 'Angle between lines trisecting a segment of a line', type: 'single', difficulty: 'Medium', question: 'The portion of the line 4x + 5y = 20 in the first quadrant is trisected by the lines L₁ and L₂ passing through the origin. The tangent of an angle between the lines L₁ and L₂ is:', options: ['8/5', '25/41', '2/5', '30/41'], answers: ['30/41'], solution: 'The segment runs from (5,0) to (0,4); trisection points are (10/3, 4/3) and (5/3, 8/3), with slopes 2/5 and 8/5. tanθ = (8/5 − 2/5)/(1 + 16/25) = 30/41.' },
  { id: 'main-2024-01-27-s1-Q66', number: 66, subject: 'Mathematics', chapter: 'Circles', topic: 'Equation of a Circle', pattern: 'Concyclic points determine parameter', type: 'single', difficulty: 'Easy', question: 'Four distinct points (2k, 3k), (1, 0), (0, 1) and (0, 0) lie on a circle for k equal to:', options: ['2/13', '3/13', '5/13', '1/13'], answers: ['5/13'], solution: 'The circle through the last three points is x² + y² − x − y = 0. Substituting (2k, 3k): 13k² = 5k, so k = 5/13.' },
  { id: 'main-2024-01-27-s1-Q67', number: 67, subject: 'Mathematics', chapter: 'Conic Sections', topic: 'Parabola', pattern: 'Shortest distance from a point to a parabola via normal', type: 'single', difficulty: 'Hard', question: 'If the shortest distance of the parabola y² = 4x from the centre of the circle x² + y² − 4x − 16y + 64 = 0 is d, then d² is equal to:', options: ['16', '24', '20', '36'], answers: ['20'], solution: 'Centre is (2, 8). For (t², 2t), minimising distance gives 4t(t² − 2) + 4(2t − 8) = 0, i.e. t = 2, point (4, 4). d² = 4 + 16 = 20.' },
  { id: 'main-2024-01-27-s1-Q68', number: 68, subject: 'Mathematics', chapter: 'Conic Sections', topic: 'Ellipse', pattern: 'Chord of ellipse with given midpoint: length', type: 'single', difficulty: 'Hard', question: 'The length of the chord of the ellipse x²/25 + y²/16 = 1, whose mid point is (1, 2/5), is equal to:', options: ['√1691/5', '√2009/5', '√1741/5', '√1541/5'], answers: ['√1691/5'], solution: 'T = S₁ gives the chord y = −8x/5 + 2 (slope −8/5). Substituting: 4x² − 8x − 15 = 0, so (Δx)² = 19; length = √19 · √(1 + 64/25) = √1691/5.' },
  { id: 'main-2024-01-27-s1-Q69', number: 69, subject: 'Mathematics', chapter: 'Limits', topic: 'Algebraic Limits: Factorisation and Rationalisation', pattern: 'Product of two radical limits via rationalisation', type: 'single', difficulty: 'Hard', question: 'If a = lim(x→0) [√(1 + √(1 + x⁴)) − √2]/x⁴ and b = lim(x→0) sin²x/(√2 − √(1 + cos x)), then the value of ab³ is:', options: ['36', '32', '25', '30'], answers: ['32'], solution: 'Rationalising: a = √2/8 (since √(1+u) ≈ √2(1 + x⁴/8)). For b: √2 − √(1+cos x) = (1 − cos x)/(√2 + √(1+cos x)), so b = (1 + cos x)(√2 + √(1+cos x)) → 2 · 2√2 = 4√2. ab³ = (√2/8)(128√2) = 32.' },
  { id: 'main-2024-01-27-s1-Q70', number: 70, subject: 'Mathematics', chapter: 'Statistics', topic: 'Variance and Standard Deviation', pattern: 'SD from sum and sum of pairwise products', type: 'single', difficulty: 'Medium', question: 'Let a₁, ..., a₁₀ be 10 observations such that Σaₖ = 50 and Σ_{∀k<j} aₖ·aⱼ = 1100. Then the standard deviation of a₁, ..., a₁₀ is equal to:', options: ['5', '√5', '10', '√115'], answers: ['√5'], solution: '(Σa)² = Σa² + 2·1100 gives Σa² = 2500 − 2200 = 300. Variance = 30 − 5² = 5, so SD = √5.' },
  { id: 'main-2024-01-27-s1-Q71', number: 71, subject: 'Mathematics', chapter: 'Relations and Functions', topic: 'Types of Relations', pattern: 'Check reflexive/symmetric/transitive', type: 'single', difficulty: 'Medium', question: 'Let S = {1, 2, 3, ..., 10}. Suppose M is the set of all the subsets of S, then the relation R = {(A, B) : A ∩ B ≠ ϕ; A, B ∈ M} is:', options: ['symmetric and reflexive only', 'reflexive only', 'symmetric and transitive only', 'symmetric only'], answers: ['symmetric only'], solution: 'A ∩ B = B ∩ A so it is symmetric; A = ∅ gives ∅ ∩ ∅ = ∅ so not reflexive; {1,2} R {2,3} R {3,4} but {1,2} is not R {3,4}, so not transitive.' },
  { id: 'main-2024-01-27-s1-Q72', number: 72, subject: 'Mathematics', chapter: 'Matrices', topic: 'Matrix Multiplication', pattern: 'Rotation matrix: inverse and product property', type: 'single', difficulty: 'Medium', question: 'Consider the matrix f(x) = [[cos x, −sin x, 0],[sin x, cos x, 0],[0, 0, 1]]. Given below are two statements:\nStatement I: f(−x) is the inverse of the matrix f(x).\nStatement II: f(x) f(y) = f(x + y).\nIn light of the above statements, choose the correct answer from the options given below:', options: ['Statement I is false but Statement II is true', 'Both Statement I and Statement II are false', 'Statement I is true but Statement II is false', 'Both Statement I and Statement II are true'], answers: ['Both Statement I and Statement II are true'], solution: 'Multiplying the rotation matrices gives f(x)f(y) = f(x+y) via compound-angle formulae; then f(x)f(−x) = f(0) = I, so f(−x) is the inverse. Both true.' },
  { id: 'main-2024-01-27-s1-Q73', number: 73, subject: 'Mathematics', chapter: 'Relations and Functions', topic: 'One-one, Onto and Bijective Functions', pattern: 'One-one/onto of function defined by prime factor', type: 'single', difficulty: 'Easy', question: 'The function f : N − {1} → N; defined by f(n) = the highest prime factor of n, is:', options: ['both one-one and onto', 'one-one only', 'onto only', 'neither one-one nor onto'], answers: ['neither one-one nor onto'], solution: 'f(2) = f(4) = 2, so not one-one. The value 1 (or any composite) is never attained, so not onto.' },
  { id: 'main-2024-01-27-s1-Q74', number: 74, subject: 'Mathematics', chapter: 'Continuity and Differentiability', topic: 'Continuity at a Point', pattern: 'Value making piecewise function continuous', type: 'single', difficulty: 'Hard', question: 'Consider the function f(x) = a(7x − 12 − x²)/(b|x² − 7x + 12|) for x < 3; f(x) = 2^{sin(x−3)/(x−[x])} for x > 3; f(3) = b, where [x] denotes the greatest integer less than or equal to x. If S denotes the set of all ordered pairs (a, b) such that f(x) is continuous at x = 3, then the number of elements in S is:', options: ['2', 'Infinitely many', '4', '1'], answers: ['1'], solution: 'For x → 3⁻, the expression equals −a/b; for x → 3⁺ the limit is 2¹ = 2. Continuity needs −a/b = 2 = b, so b = 2, a = −4: a single pair.' },
  { id: 'main-2024-01-27-s1-Q75', number: 75, subject: 'Mathematics', chapter: 'Definite Integrals and Area Under Curves', topic: 'Fundamental Theorem and Evaluation', pattern: 'Rationalised integral of reciprocal sum of square roots', type: 'single', difficulty: 'Medium', question: 'If ∫₀¹ 1/(√(3 + x) + √(1 + x)) dx = a + b√2 + c√3, where a, b, c are rational numbers, then 2a + 3b − 4c is equal to:', options: ['4', '10', '7', '8'], answers: ['8'], solution: 'Rationalise: integrand = (√(3+x) − √(1+x))/2, giving (1/3)[(8 − 3√3) − (2√2 − 1)] = 3 − (2/3)√2 − √3. So a = 3, b = −2/3, c = −1 and 2a + 3b − 4c = 6 − 2 + 4 = 8.' },
  { id: 'main-2024-01-27-s1-Q76', number: 76, subject: 'Mathematics', chapter: 'Definite Integrals and Area Under Curves', topic: 'Properties of Definite Integrals', pattern: 'King\'s property (x → a+b−x) to simplify integral', type: 'single', difficulty: 'Hard', question: 'If (a, b) be the orthocentre of the triangle whose vertices are (1, 2), (2, 3) and (3, 1), and I₁ = ∫ₐᵇ x sin(4x − x²) dx, I₂ = ∫ₐᵇ sin(4x − x²) dx, then 36 I₁/I₂ is equal to:', options: ['72', '88', '80', '66'], answers: ['72'], solution: 'Altitudes y = −x + 4 and y − 2 = (x−1)/2 meet at (5/3, 7/3), so a + b = 4. The integrand sin(4x−x²) is symmetric about x = 2, so I₁ = ∫(4−x)sin(...) gives I₁ = 2I₂. Hence 36 × 2 = 72.' },
  { id: 'main-2024-01-27-s1-Q77', number: 77, subject: 'Mathematics', chapter: 'Differential Equations', topic: 'Variable Separable Equations', pattern: 'Solutions of two separable ODEs equal at time t', type: 'single', difficulty: 'Hard', question: 'Let x = x(t) and y = y(t) be solutions of the differential equations dx/dt + ax = 0 and dy/dt + by = 0 respectively, a, b ∈ R. Given that x(0) = 2; y(0) = 1 and 3y(1) = 2x(1), the value of t, for which x(t) = y(t), is:', options: ['log_{3/2} 2', 'log₄ 3', 'log₃ 4', 'log_{4/3} 2'], answers: ['log_{4/3} 2'], solution: 'x = 2e^{−at}, y = e^{−bt}; 3y(1) = 2x(1) gives e^{b−a} = 3/4. Setting x = y: e^{(b−a)t} = 1/2, so (3/4)ᵗ = 1/2 and t = log_{4/3} 2.' },
  { id: 'main-2024-01-27-s1-Q78', number: 78, subject: 'Mathematics', chapter: 'Vector Algebra', topic: 'Scalar Triple Product and Coplanarity', pattern: 'Triple product from a × c = b and a · c = 3', type: 'single', difficulty: 'Hard', question: 'If a = î + 2ĵ + k̂, b = 3(î − ĵ + k̂) and c be the vector such that a × c = b and a · c = 3, then a · ((c × b) − b − c) is equal to:', options: ['32', '24', '20', '36'], answers: ['24'], solution: 'a·(c×b) = b·(a×c) = |b|² = 27. a·b = 3(1 − 2 + 1) = 0 and a·c = 3. Result = 27 − 0 − 3 = 24.' },
  { id: 'main-2024-01-27-s1-Q79', number: 79, subject: 'Mathematics', chapter: 'Three Dimensional Geometry', topic: 'Line and Plane: Intersection, Angle, Foot and Image', pattern: 'Distance of a point from a line along given lines', type: 'single', difficulty: 'Medium', question: 'The distance of the point (7, −2, 11) from the line (x−6)/1 = (y−4)/0 = (z−8)/3 along the line (x−5)/2 = (y−1)/(−3) = (z−5)/6 is:', options: ['12', '14', '18', '21'], answers: ['14'], solution: 'Point (7+2s, −2−3s, 11+6s) lies on the first line when y = 4, so s = −2, giving (3, 4, −1) (check x: t = −3, z: 8 − 9 = −1). Distance = 2 × √(4+9+36) = 2 × 7 = 14.' },
  { id: 'main-2024-01-27-s1-Q80', number: 80, subject: 'Mathematics', chapter: 'Three Dimensional Geometry', topic: 'Angle Between Lines and Shortest Distance', pattern: 'Shortest distance between skew lines', type: 'single', difficulty: 'Medium', question: 'If the shortest distance between the lines (x−4)/1 = (y+1)/2 = z/(−3) and (x−λ)/2 = (y+1)/4 = (z−2)/(−5) is 6/√5, then the sum of all possible values of λ is:', options: ['5', '8', '7', '10'], answers: ['8'], solution: 'd₁ × d₂ = (1,2,−3) × (2,4,−5) = (2, −1, 0), magnitude √5. Distance = |2(λ − 4)|/√5 = 6/√5, so λ = 7 or 1; sum 8.' },
  { id: 'main-2024-01-27-s1-Q81', number: 81, subject: 'Mathematics', chapter: 'Complex Numbers', topic: 'Cube Roots of Unity', pattern: 'Sums of powers of expressions in ω', type: 'numerical', difficulty: 'Medium', question: 'If α satisfies the equation x² + x + 1 = 0 and (1 + α)⁷ = A + Bα + Cα², A, B, C ≥ 0, then 5(3A − 2B − C) is equal to ______.', answers: ['5'], solution: 'α = ω, 1 + ω = −ω², so (1+ω)⁷ = −ω¹⁴ = −ω² = 1 + ω. Thus A = 1, B = 1, C = 0 and 5(3 − 2) = 5.' },
  { id: 'main-2024-01-27-s1-Q82', number: 82, subject: 'Mathematics', chapter: 'Sequences and Series', topic: 'Arithmetico-Geometric Series', pattern: 'Arithmetico-geometric infinite series to find p', type: 'numerical', difficulty: 'Medium', question: 'If 8 = 3 + (1/4)(3 + p) + (1/4²)(3 + 2p) + (1/4³)(3 + 3p) + ... ∞, then the value of p is ______.', answers: ['9'], solution: 'Σ3/4ᵏ = 1 and Σ k p/4ᵏ = p·(1/4)/(3/4)² = 4p/9. So 8 = 3 + 1 + 4p/9 and p = 9.' },
  { id: 'main-2024-01-27-s1-Q83', number: 83, subject: 'Mathematics', chapter: 'Trigonometric Equations', topic: 'Equations Reducible to Quadratic Form and Factorisation', pattern: 'Range of a for which a trigonometric equation is solvable', type: 'numerical', difficulty: 'Hard', question: 'Let the set of all a ∈ R such that the equation cos 2x + a sin x = 2a − 7 has a solution be [p, q] and r = tan 9° − tan 27° − 1/cot 63° + tan 81°, then pqr is equal to ______.', answers: ['48'], solution: 'With s = sin x: 2s² − as + 2a − 8 = 0, i.e. (s − 2)(2s + 4 − a) = 0, so s = a/2 − 2 ∈ [−1, 1] gives a ∈ [2, 6]. And r = (tan9° + tan81°) − (tan27° + tan63°) = 2/sin18° − 2/sin54° = 4. pqr = 2·6·4 = 48.' },
  { id: 'main-2024-01-27-s1-Q84', number: 84, subject: 'Mathematics', chapter: 'Matrices', topic: 'Invertible Matrices and Matrix Polynomials', pattern: 'Trace and determinant of B from AB column conditions', type: 'numerical', difficulty: 'Hard', question: 'Let A = [[2,0,1],[1,1,0],[1,0,1]], B = [B₁ B₂ B₃], where B₁, B₂, B₃ are column matrices, and AB₁ = (1,0,0)ᵀ, AB₂ = (2,3,0)ᵀ, AB₃ = (3,2,1)ᵀ. If α = |B| and β is the sum of all the diagonal elements of B, then α³ + β³ is equal to ______.', answers: ['28'], solution: 'AB = C = [[1,2,3],[0,3,2],[0,0,1]] with |C| = 3 and |A| = 1, so |B| = 3. A⁻¹ = [[1,0,−1],[−1,1,1],[−1,0,2]]; diagonal of A⁻¹C is 1, 1, −1, so trace = 1. α³ + β³ = 27 + 1 = 28.' },
  { id: 'main-2024-01-27-s1-Q85', number: 85, subject: 'Mathematics', chapter: 'Continuity and Differentiability', topic: 'Second-order Derivatives', pattern: 'Polynomial with f′, f″, f‴ values: find f′(10)', type: 'numerical', difficulty: 'Medium', question: 'Let f(x) = x³ + x²f′(1) + x f″(2) + f‴(3), x ∈ R. Then f′(10) is equal to ______.', answers: ['202'], solution: 'Let f′(1) = a, f″(2) = b. f′ = 3x² + 2ax + b, f″ = 6x + 2a, f‴ = 6. Then a = 3 + 2a + b and b = 12 + 2a give a = −5, b = 2. f′(10) = 300 − 100 + 2 = 202.' },
  { id: 'main-2024-01-27-s1-Q86', number: 86, subject: 'Mathematics', chapter: 'Continuity and Differentiability', topic: 'Differentiability and Its Relation to Continuity', pattern: 'Inequality forces f(x) − ln x − x constant', type: 'numerical', difficulty: 'Hard', question: 'Let for a differentiable function f : (0, ∞) → R, f(x) − f(y) ≥ log_e(x/y) + x − y, ∀x, y ∈ (0, ∞). Then Σ_{n=1}^{20} f′(1/n²) is equal to ______.', answers: ['2890'], solution: 'Let g(x) = f(x) − ln x − x; the condition gives g(x) ≥ g(y) for all x, y, so g is constant and f′(x) = 1/x + 1. Then Σ f′(1/n²) = Σ(n² + 1) = 2870 + 20 = 2890.' },
  { id: 'main-2024-01-27-s1-Q87', number: 87, subject: 'Mathematics', chapter: 'Definite Integrals and Area Under Curves', topic: 'Area Between Two Curves', pattern: 'Area of region bounded by parabolas and lines', type: 'numerical', difficulty: 'Hard', question: 'Let the area of the region {(x, y) : x − 2y + 4 ≥ 0, x + 2y² ≥ 0, x + 4y² ≤ 8, y ≥ 0} be m/n, where m and n are coprime numbers. Then m + n is equal to ______.', answers: ['119'], solution: 'Integrate in y: for 0 ≤ y ≤ 1 the left bound is x = −2y² and for 1 ≤ y ≤ 3/2 it is x = 2y − 4; the right bound is x = 8 − 4y². Area = ∫₀¹(8 − 2y²)dy + ∫₁^{3/2}(12 − 2y − 4y²)dy = 22/3 + 19/12 = 107/12, so m + n = 119.' },
  { id: 'main-2024-01-27-s1-Q88', number: 88, subject: 'Mathematics', chapter: 'Differential Equations', topic: 'Equations Reducible to Standard Forms', pattern: 'Substitution t = 2x + 3y for a near-homogeneous DE', type: 'numerical', difficulty: 'Hard', question: 'If the solution of the differential equation (2x + 3y − 2)dx + (4x + 6y − 7)dy = 0, y(0) = 3, is αx + βy + 3 log_e|2x + 3y − γ| = 6, then α + 2β + 3γ is equal to ______.', answers: ['29'], solution: 'Put t = 2x + 3y: dt/dx = (t − 8)/(2t − 7), so ∫(2 + 9/(t−8))dt = x + c, giving x + 2y + 3 ln|2x + 3y − 8| = C. y(0) = 3 gives C = 6. So α = 1, β = 2, γ = 8 and the sum is 1 + 4 + 24 = 29.' },
  { id: 'main-2024-01-27-s1-Q89', number: 89, subject: 'Mathematics', chapter: 'Vector Algebra', topic: 'Scalar (Dot) Product and Projection', pattern: 'Least integer α for acute angle between vectors', type: 'numerical', difficulty: 'Easy', question: 'The least positive integral value of α, for which the angle between the vectors α î − 2ĵ + 2k̂ and α î + 2α ĵ − 2k̂ is acute, is ______.', answers: ['5'], solution: 'Acute requires the dot product α² − 4α − 4 > 0, i.e. α > 2 + 2√2 ≈ 4.83, so the least integer is 5.' },
  { id: 'main-2024-01-27-s1-Q90', number: 90, subject: 'Mathematics', chapter: 'Probability', topic: 'Random Variables and Probability Distributions', pattern: 'Geometric distribution probabilities ratio', type: 'numerical', difficulty: 'Medium', question: 'A fair die is tossed repeatedly until a six is obtained. Let X denote the number of tosses required and let a = P(X = 3), b = P(X ≥ 3) and c = P(X ≥ 6 | X > 3). Then (b + c)/a is equal to ______.', answers: ['12'], solution: 'With p = 1/6: a = (5/6)²(1/6) = 25/216, b = (5/6)² = 25/36, and by memorylessness c = P(X ≥ 6)/P(X ≥ 4) = (5/6)² = 25/36. (b + c)/a = (50/36)(216/25) = 12.' },
] };
